const json=s=>JSON.stringify(s).replace(/</g,'\\u003c');const href=(u,text)=>`<a href="${esc(u)}">${esc(text)}</a>`;const p=s=>`<p>${esc(s)}</p>`;const item=(u,name,desc)=>`<div class="guide-item">${href(u,name)}${desc?p(desc):''}</div>`;
const clusters=plan.clusters.map(([id,title,tool,knowledge])=>({id,title,tool,knowledge,slug:tool.split('/')[2]}));const descriptions=[
'Prüfe Seitensignale, plane Migrationen und erzeuge nachvollziehbare technische SEO-Artefakte.','Plane wiederholbare KI-Sichtbarkeitstests, Quellenprüfung und konsistente Entitätsdaten.','Entwickle Briefings, analysiere Texte und dokumentiere redaktionelle Entscheidungen.','Berechne Kennzahlen und Szenarien aus deinen eigenen Exporten und Annahmen.','Verarbeite Daten, teste reguläre Ausdrücke und experimentiere mit Webtechnologien.','Gestalte zugängliche Oberflächen, Layouts, Farben und wiederverwendbare Gestaltungswerte.','Konvertiere, komprimiere und bearbeite eigene lokale Bilder und Audiodateien.','Entwickle Levelmuster, Rasterkarten, Spiellogik und reproduzierbare Simulationsmodelle.','Experimentiere mit synthetischen Klängen, generativer Kunst und verzweigten Geschichten.','Plane Tests, dokumentiere Entscheidungen und überprüfe Qualität anhand definierter Kriterien.'];
