function fieldsHtml(tool,defaults={}){return Object.entries(tool.fields).map(([k,f])=>{let id='field-'+k,v=defaults[k]??f.value;let control;if(f.type==='textarea')control=`<textarea id="${id}" name="${k}" rows="4" spellcheck="false" maxlength="500000">${esc(v)}</textarea>`;else if(f.type==='select')control=`<select id="${id}" name="${k}">${f.options.map(x=>`<option value="${esc(x)}"${x===v?' selected':''}>${x==='\t'?'Tabulator':esc(x)}</option>`).join('')}</select>`;else if(f.type.endsWith('file'))control=`<input id="${id}" name="${k}" type="file" accept="${f.type==='audiofile'?'audio/*':'image/png,image/jpeg,image/webp,image/gif,image/bmp,image/avif'}"${f.type==='imagesfile'?' multiple':''}>`;else control=`<input id="${id}" name="${k}" type="${f.type==='url'?'text':f.type}"${f.type==='url'?' inputmode="url"':''} value="${esc(v)}"${f.type==='number'?` min="${f.min}" max="${f.max}" step="${f.step}" required`:''}${f.type==='text'?' maxlength="500000"':''}>`;return `<div class="field"><label for="${id}">${esc(f.label)}</label>${control}</div>`;}).join('');}
function presetPanel(row){const entries=knowledge.filter(v=>v.tool===row.id);if(!entries.length)return '';const presets=entries.filter(v=>v.preset);return `<section class="preset-panel" id="vorlagen" data-knowledge-ui><h2>Passende Praxisvorlagen</h2><p class="small muted">${presets.length? 'Wähle ein Beispiel. Übernehmen ersetzt die Eingabewerte, berechnet aber nicht automatisch; der vorherige Stand kann einmal wiederhergestellt werden.':'Nutze die Prüfschritte mit deinen eigenen Dateien.'}</p>${presets.length?`<label for="preset-select">Anwendungsfall</label><select id="preset-select"><option value="">Vorlage auswählen</option>${presets.map(v=>`<option value="${v.id}">${esc(v.title)}</option>`).join('')}</select><p id="preset-summary" class="small muted"></p><div class="controls"><button type="button" id="preset-apply" disabled>Vorlage übernehmen</button><button type="button" class="secondary" id="preset-undo" disabled>Vorherige Eingaben</button></div><p id="preset-status" class="small" role="status"></p><script type="application/json" id="preset-data">${json(presets.map(({id,title,scenario,check,limit,preset})=>({id,title,scenario,check,limit,preset})))}</script>`:''}<ul class="preset-links">${entries.map(v=>`<li>${href(v.entryRoute,v.title)}</li>`).join('')}</ul></section>`;}
