const projects=plan.projects.filter(r=>r[1]==='Projekt');const lab=plan.projects.filter(r=>r[1]==='Labor');const projectInfo=[['https://kalenderwoche.info/','ISO-Kalenderwochen und zeitliche Orientierung','Eine Kalenderwoche muss insbesondere an Jahresgrenzen korrekt definiert werden. Die Plattform ist ein Beispiel für strukturierte Datumsinformationen und wiederkehrende Suchaufgaben.','Prüfaufgaben: Kalenderwochen 1 und 53, Jahreswechsel, mehrsprachige Darstellungen.','T058'],['https://jahreskalender.org/','Jahreskalender und Datumsinformationen','Jahreskalender eignen sich für eine nachvollziehbare Informationsarchitektur, in der Jahre, Monate und Datumsregeln konsistent abgebildet werden.','Prüfaufgaben: Schaltjahre, regionale Daten, eindeutige Verlinkung und verständliche Datumsformate.','T005'],['https://schlafrechner.org/','Schlafbezogene Orientierung und Rechner','Rechner zu Schlafthemen sollten ihre Annahmen transparent erläutern. Ergebnisse sind Orientierungshilfen und keine medizinische Diagnose.','Prüfaufgaben: Eingabegrenzen, nachvollziehbare Berechnung, Informationsstand und fachliche Grenzen.','T104'],['https://matthias-boehm.com/','Persönliche Expertenwebsite','Die persönliche Website verbindet die berufliche Positionierung in SEO, GEO und digitaler Produktentwicklung mit Fachwissen und dem Projektportfolio.','Prüfaufgaben: konsistente Personenidentität, semantische Struktur, interne Links und eindeutige Positionierung.','T016']];
