const labInfo={L05:['T085',{biome:'Wald'},'Experiment: Filtere die Wald-Muster und vergleiche die Lernaufgaben. Verwende ein Muster in einer sicheren Einführungsphase, bevor du weitere Mechaniken kombinierst.'],L06:['T101',{seed:'lichtbiologie',phase:72,curves:26,color:'#b38948'},'Experiment: Ändere die Morph-Phase in Zehnerschritten und vergleiche Kurvenverläufe. Ein identischer Seed erzeugt dieselbe Geometrie.'],L07:['T095',{wave:'triangle',freq:330,cutoff:950,attack:.12,release:.5},'Experiment: Höre denselben Ton mit Sinus und Dreieck. Verändere danach nur die Tiefpassfrequenz. Lautstärke niedrig halten.'],L09:['T102',{start:'ufer',scenes:'ufer | Du erreichst ein stilles Moor.\nsteg | Auf dem Steg entdeckst du eine Spur.\nwald | Im Wald leuchtet eine kleine Laterne.\nende | Du findest den Weg nach Hause.',edges:'ufer | Über den Steg | steg\nufer | Durch den Wald | wald\nsteg | Weiter zur Laterne | wald\nwald | Nach Hause | ende'},'Experiment: Teste beide Wege durch eine kurze eigenständige Geschichte. Ergänze eine Szene und prüfe, ob sie erreichbar ist.'],L11:['T092',{seed:'moorgebiet-01',width:40,height:24,water:45},'Experiment: Vergleiche zwei Karten mit demselben Seed und unterschiedlichen Wasserschwellen. Die Darstellung ist ein stilisiertes Geländemodell, keine echte Naturprognose.'],L12:['T070',{},'Experiment: Bediene die Demo ausschließlich mit Tab, Umschalt+Tab und Enter. Vergleiche den sichtbaren Fokus mit dem ausdrücklich gekennzeichneten Negativbeispiel.']};
for(let [id,kind,name,route,brief] of lab){let body,script;if(labInfo[id]){let [tid,defaults,desc]=labInfo[id],r=trows.find(x=>x.id===tid);body=hero('Interaktives Experiment',name,desc,`<p>Lab-Demo · ${esc(id)}</p>${href(r.route,'Vollständiges Werkzeug')}`)+toolUI(r,defaults)+`<section class="section prose"><h2>Was das Experiment zeigt</h2>${p(r.tool.method)}<h2>Grenzen</h2>${p(r.tool.limit)}</section>`;script='app.mjs';}else{let strategy=id==='L08';let desc=strategy?'Eine kleine rundenbasierte Karte mit zwei fiktiven Fraktionen. Übernimm benachbarte Felder, verwalte Energie und beende deine Runde.':'Ein vereinfachtes Rastermodell für Oberflächenwasser, Versickerung und Abfluss. Ergänze Grünflächen und vergleiche die Mengenbilanz.';body=hero('Spielbares Experiment',name,desc)+`<section class="section"><div class="pane" data-demo="${strategy?'strategy':'water'}"></div></section><section class="prose"><h2>So funktioniert es</h2>${p(strategy?'Wähle eine Zelle per Klick oder Pfeiltasten auf der fokussierten Karte. Freie Nachbarfelder kosten eine Energie, gegnerische drei. Pro Runde erhältst du drei Energie bis maximal zwölf. Die Gegenseite übernimmt bis zu zwei erreichbare Felder. Nach 30 Runden gewinnt die Fraktion mit mehr Feldern.':'Regenschauer erhöhen Wasser auf allen Zellen; Grünflächen absorbieren pro Zeitschritt mehr Wasser. Wasser fließt vereinfachend zu niedrigeren Nachbaroberflächen und am unteren Rand ab. Die Bilanz zeigt Regen, gespeichertes Wasser, Versickerung und Abfluss in Modell-Einheiten.') }<div class="note">${p(strategy?'Kompakter spielbarer Prototyp, keine historische Militärsimulation.':'Illustratives Modell ohne kalibrierte Einheiten, Niederschlagsdaten oder reale Bodenparameter. Nicht für hydrologische Prognosen oder Bauentscheidungen verwenden.')}</div></section>`;script='demos.mjs';}page({route,title:name,description:brief,body,noindex:!!labInfo[id],script,parts:[['/','Portfolio'],['/labor/','Labor'],[route,name]]});}
